/**
 * Independent synthetic export fixtures for the web reader tests.
 *
 * Everything here is generated at run time and contains no real chat data:
 * account IDs, peer IDs, message UUIDs and text are arbitrary, and media are
 * tiny generated byte strings. The fixture deliberately includes
 *
 * - integers larger than 2^53 written as bare JSON numbers (they round under a
 *   naive JSON.parse, so raw_json must stay a string),
 * - HTML/script text and spreadsheet formula text,
 * - real media bytes, including one large file for byte-range tests,
 * - a plaintext chat.sqlite and the standard English export filenames,
 *
 * so the web reader can be tested against a realistic but separate producer.
 */
import { createHash } from 'node:crypto';
import fs from 'node:fs';
import { createRequire } from 'node:module';
import os from 'node:os';
import path from 'node:path';

const require = createRequire(import.meta.url);

export const ACCOUNT_A = '8100000000000011';
export const ACCOUNT_B = '8210000000000022';
export const PEER_A = '7300000000000044';
export const PEER_B = '7300000000000055';
export const CONVERSATION_A = `0:1:${ACCOUNT_A}:${PEER_A}`;
export const CONVERSATION_B = `0:1:${ACCOUNT_B}:${PEER_B}`;

export const UUID = {
  text: 'aaaaaaaa-0000-4000-8000-000000000001',
  html: 'aaaaaaaa-0000-4000-8000-000000000002',
  formula: 'aaaaaaaa-0000-4000-8000-000000000003',
  voice: 'aaaaaaaa-0000-4000-8000-000000000004',
  sticker: 'aaaaaaaa-0000-4000-8000-000000000005',
  huge: 'aaaaaaaa-0000-4000-8000-000000000006',
  unavailable: 'aaaaaaaa-0000-4000-8000-000000000007',
  conversationB: 'bbbbbbbb-0000-4000-8000-000000000001',
};

// 2^53 + 1 and a 19-digit index: both are unsafe as JavaScript numbers.
export const BIG_SERVER_ID = '9007199254740993';
export const BIG_INDEX = '1234567890123456789';

export const BUBBLE_ID = '7100000000000000123';

export const MEDIA = {
  voice: 'attachments/voice/v1.m4a',
  sticker: 'attachments/stickers/s1.png',
  bubbleSelf: `attachments/bubbles/${BUBBLE_ID}/self.png`,
  bubbleGuest: `attachments/bubbles/${BUBBLE_ID}/guest.png`,
  inlineEmoji: 'attachments/inline_emoji/smile.png',
  big: 'attachments/media/big.bin',
  text: 'attachments/media/note.txt',
};

const BIG_FILE_BYTES = 256 * 1024;
const TEXT_FILE = 'range-test-payload\nsecond line\nthird line\n';

function bytes(pattern, length) {
  const out = Buffer.alloc(length);
  for (let index = 0; index < length; index += 1) out[index] = pattern[(index) % pattern.length];
  return out;
}

/** Serialize JSON while keeping chosen numeric fields as exact literals. */
function rawLine(row, literals = {}) {
  let text = JSON.stringify(row);
  for (const [key, literal] of Object.entries(literals)) {
    text = text.replace(`"@@${key}@@"`, literal);
  }
  return text;
}

function sha256(buffer) {
  return createHash('sha256').update(buffer).digest('hex');
}

function writeFile(root, relative, buffer) {
  const target = path.join(root, relative);
  fs.mkdirSync(path.dirname(target), { recursive: true });
  fs.writeFileSync(target, buffer);
  return target;
}

function writeJson(root, relative, value) {
  return writeFile(root, relative, Buffer.from(JSON.stringify(value, null, 1), 'utf8'));
}

function messageRow({ uuid, conversationId, conversationName, sender, senderName, created,
                      type, typeName, content, serverId, orderIndex, ext = '{}',
                      deleted = 0, localMedia = [], media = null, bubble = null }) {
  const accountUid = conversationId.split(':')[2] || '';
  const row = {
    msg_uuid: uuid,
    msg_server_id: '@@msg_server_id@@',
    conversation_id: conversationId,
    conversation_short_id: '@@short_id@@',
    conversation_type: 1,
    type,
    index_in_conversation: '@@index_in_conversation@@',
    order_index: '@@order_index@@',
    status: 5,
    net_status: 0,
    version: 0,
    deleted,
    created_time: created,
    sender,
    content: JSON.stringify(content),
    ext,
    local_info: '',
    read_status: 1,
    sec_sender: '',
  };
  const meta = {
    account_uid: String(accountUid),
    conversation_name: conversationName,
    time: '2026-10-27 12:00:00',
    timezone: 'Asia/Shanghai',
    sender_name: senderName,
    type_name: typeName,
    text: typeof content?.text === 'string' ? content.text : `[${typeName}]`,
    local_media: [...localMedia],
    bubble: bubble || { id: BUBBLE_ID, side: '1', source: 'a:chat_bubble', available: true, applied: true },
  };
  if (media) meta.media = media;
  row._export = meta;
  const json = rawLine(row, {
    msg_server_id: String(serverId),
    conversation_short_id: '7370387642841629193',
    index_in_conversation: String(orderIndex),
    order_index: String(orderIndex),
  });
  return { row, meta, json };
}

/** Build a complete synthetic export tree and return handles for tampering. */
export function makeExport(rootDir) {
  const dir = rootDir || fs.mkdtempSync(path.join(os.tmpdir(), 'dsweb-export-'));
  fs.mkdirSync(dir, { recursive: true });

  const mediaBuffers = {
    [MEDIA.voice]: bytes([0x00, 0x00, 0x00, 0x1c, 0x66, 0x74, 0x79, 0x70], 4096),
    [MEDIA.sticker]: bytes([0x89, 0x50, 0x4e, 0x47], 2048),
    [MEDIA.bubbleSelf]: bytes([0x89, 0x50, 0x4e, 0x47, 0x01], 512),
    [MEDIA.bubbleGuest]: bytes([0x89, 0x50, 0x4e, 0x47, 0x02], 512),
    [MEDIA.inlineEmoji]: bytes([0x89, 0x50, 0x4e, 0x47, 0x03], 256),
    [MEDIA.big]: bytes([0x41, 0x42, 0x43, 0x44, 0x45, 0x46, 0x47, 0x48], BIG_FILE_BYTES),
    [MEDIA.text]: Buffer.from(TEXT_FILE, 'utf8'),
  };
  for (const [relative, buffer] of Object.entries(mediaBuffers)) writeFile(dir, relative, buffer);
  const hashes = Object.fromEntries(Object.entries(mediaBuffers)
    .map(([relative, buffer]) => [relative, sha256(buffer)]));

  const mediaEntry = (kind, relative, resourceId) => ({
    resource_id: resourceId, kind, status: 'ok', path: relative,
    bytes: mediaBuffers[relative].length, sha256: hashes[relative],
  });
  const messages = {};

  const accountAMessages = [
    messageRow({
      uuid: UUID.text, conversationId: CONVERSATION_A, conversationName: 'Synthetic Chat A',
      sender: Number(ACCOUNT_A), senderName: 'Me', created: 1793000000000,
      type: 7, typeName: 'Text', content: { text: 'hello [smile] world' },
      serverId: '7000000000000000001', orderIndex: '1000',
    }),
    messageRow({
      uuid: UUID.html, conversationId: CONVERSATION_A, conversationName: 'Synthetic Chat A',
      sender: Number(PEER_A), senderName: 'Peer A', created: 1793000001000,
      type: 7, typeName: 'Text',
      content: { text: '<script>alert("xss")</script> & <b>bold</b> "quoted"' },
      serverId: '7000000000000000002', orderIndex: '2000', deleted: 1,
    }),
    messageRow({
      uuid: UUID.formula, conversationId: CONVERSATION_A, conversationName: 'Synthetic Chat A',
      sender: Number(PEER_A), senderName: 'Peer A', created: 1793000002000,
      type: 7, typeName: 'Text', content: { text: '=SUM(A1:A2)\nsecond line' },
      serverId: '7000000000000000003', orderIndex: '3000',
    }),
    messageRow({
      uuid: UUID.voice, conversationId: CONVERSATION_A, conversationName: 'Synthetic Chat A',
      sender: Number(ACCOUNT_A), senderName: 'Me', created: 1793000003000,
      type: 17, typeName: 'Voice',
      content: { duration: 1500, url: { url_list: ['https://example.invalid/v'] } },
      serverId: '7000000000000000004', orderIndex: '4000',
      localMedia: [MEDIA.voice],
      media: { kind: 'voice', status: 'ok', path: MEDIA.voice, resource_id: 'voice_v1' },
    }),
    messageRow({
      uuid: UUID.sticker, conversationId: CONVERSATION_A, conversationName: 'Synthetic Chat A',
      sender: Number(PEER_A), senderName: 'Peer A', created: 1793000004000,
      type: 5, typeName: 'Sticker',
      content: { display_name: 'happy', url: { url_list: ['https://example.invalid/s'] } },
      serverId: '7000000000000000005', orderIndex: '5000',
      localMedia: [MEDIA.sticker],
      media: { kind: 'emoji', status: 'ok', path: MEDIA.sticker, resource_id: 'emoji_s1' },
    }),
    messageRow({
      uuid: UUID.huge, conversationId: CONVERSATION_A, conversationName: 'Synthetic Chat A',
      sender: Number(ACCOUNT_A), senderName: 'Me', created: 1793000005000,
      type: 7, typeName: 'Text', content: { text: 'unsafe integer row' },
      serverId: BIG_SERVER_ID, orderIndex: BIG_INDEX,
    }),
    messageRow({
      uuid: UUID.unavailable, conversationId: CONVERSATION_A, conversationName: 'Synthetic Chat A',
      sender: Number(PEER_A), senderName: 'Peer A', created: 1793000006000,
      type: 5, typeName: 'Sticker',
      content: { display_name: 'gone', url: { url_list: ['https://example.invalid/gone'] } },
      serverId: '7000000000000000007', orderIndex: '7000',
      media: { kind: 'emoji', status: 'missing_url', resource_id: 'emoji_missing' },
    }),
  ];
  const accountBMessages = [
    messageRow({
      uuid: UUID.conversationB, conversationId: CONVERSATION_B, conversationName: 'Synthetic Chat B',
      sender: Number(ACCOUNT_B), senderName: 'Me', created: 1793001000000,
      type: 7, typeName: 'Text', content: { text: 'second conversation' },
      serverId: '7000000000000000008', orderIndex: '1000',
    }),
  ];

  for (const item of accountAMessages) {
    if (!['voice', 'sticker', 'unavailable'].includes(item.row.msg_uuid)) continue;
    const media = item.meta.media || { kind: 'emoji', status: 'missing_url', resource_id: 'emoji_missing' };
    messages[`${ACCOUNT_A}:${item.row.msg_uuid}`] = { ...media };
  }
  messages[`${ACCOUNT_A}:${UUID.unavailable}`] = { kind: 'emoji', status: 'missing_url', resource_id: 'emoji_missing' };

  writeJson(dir, 'media_manifest.json', {
    resources: [
      mediaEntry('voice', MEDIA.voice, 'voice_v1'),
      mediaEntry('emoji', MEDIA.sticker, 'emoji_s1'),
    ],
    messages,
    statistics: { voice: { messages_downloaded: 1 }, emoji: { messages_downloaded: 1 } },
  });
  writeJson(dir, 'decoration_manifest.json', {
    bubbles: {
      [BUBBLE_ID]: {
        sides: {
          1: { path: MEDIA.bubbleSelf, width: 96, height: 96, nine_patch: { padding: [1, 1, 1, 1], slice: [1, 1, 1, 1], scale: 3 } },
          0: { path: MEDIA.bubbleGuest, width: 96, height: 96, nine_patch: { padding: [1, 1, 1, 1], slice: [1, 1, 1, 1], scale: 3 } },
        },
        properties: { tc: '#112233' },
        corners: { top_left_self: { path: MEDIA.bubbleSelf, width: 96, height: 96 } },
      },
    },
    inline_emoji: { '[smile]': { path: MEDIA.inlineEmoji, width: 32, height: 32, version: 1 } },
  });

  const accountMeta = {
    [ACCOUNT_A]: { name: 'Synthetic Account A', conversationCount: 1 },
    [ACCOUNT_B]: { name: 'Synthetic Account B', conversationCount: 1 },
  };

  for (const [uid, info] of Object.entries(accountMeta)) {
    const rows = uid === ACCOUNT_A ? accountAMessages : accountBMessages;
    const folder = path.join(dir, uid);
    fs.mkdirSync(path.join(folder, 'conversations'), { recursive: true });
    fs.mkdirSync(path.join(folder, 'transcripts'), { recursive: true });

    const jsonl = rows.map((item) => item.json).join('\n') + '\n';
    writeFile(dir, `${uid}/messages.jsonl`, Buffer.from(jsonl, 'utf8'));
    writeJson(dir, `${uid}/contacts.json`, [
      { uid, nickname: info.name, remark_name: '' },
      { uid: PEER_A, nickname: 'Peer A', remark_name: '' },
    ]);
    writeJson(dir, `${uid}/conversation_metadata.json`, { conversation_core: [], conversation_list: [], participant: [], attchment: [] });
    writeJson(dir, `${uid}/statistics.json`, {
      uid, nickname: info.name, message_count: rows.length,
      conversation_count: info.conversationCount,
      conversations: rows.map((item) => ({
        conversation_id: item.row.conversation_id,
        name: item.meta.conversation_name,
        count: 1,
        page: 'conversations/conversation_001_page_001.html',
        txt: 'transcripts/conversation_001.txt',
      })),
    });
    writeFile(dir, `${uid}/messages.csv`,
      Buffer.from(`\ufeffAccount UID,Conversation,Text\n${uid},,"${'=SUM(A1:A2)'}"\n`, 'utf8'));

    // A plaintext SQLite file that the web reader must never write to.
    try {
      // eslint-disable-next-line no-undef
      const { DatabaseSync } = require('node:sqlite');
      const database = new DatabaseSync(path.join(folder, 'chat.sqlite'));
      database.exec('CREATE TABLE msg (msg_uuid TEXT PRIMARY KEY, msg_server_id TEXT, content TEXT)');
      const insert = database.prepare('INSERT INTO msg VALUES (?, ?, ?)');
      for (const item of rows) insert.run(item.row.msg_uuid, String(item.row.msg_server_id), item.row.content);
      database.close();
    } catch {
      writeFile(dir, `${uid}/chat.sqlite`, Buffer.from('SQLite format 3\u0000', 'binary'));
    }

    writeFile(dir, `${uid}/conversations/conversation_001_page_001.html`,
      Buffer.from('<!doctype html><html lang="zh-CN"><body>合成会话</body></html>', 'utf8'));
    writeFile(dir, `${uid}/transcripts/conversation_001.txt`, Buffer.from('Conversation: synthetic\n', 'utf8'));
    writeFile(dir, `${uid}/index.html`,
      Buffer.from(`<!doctype html><html lang="zh-CN"><body><a href="${uid}/index.html">账号</a></body></html>`, 'utf8'));
  }

  const accountsSummary = Object.entries(accountMeta).map(([uid, info]) => ({
    uid, nickname: info.name, message_count: uid === ACCOUNT_A ? accountAMessages.length : accountBMessages.length,
    conversation_count: info.conversationCount, first: '2026-10-27 12:00:00', last: '2026-10-27 12:00:01',
  }));
  writeJson(dir, 'export_summary.json', {
    app: 'Duoshan',
    app_version: 'synthetic',
    timezone: 'Asia/Shanghai',
    total_message_count: accountAMessages.length + accountBMessages.length,
    account_count: accountsSummary.length,
    accounts: accountsSummary,
    media_and_presentation: {
      rendered: {
        inline_emoji_occurrences: 1,
        original_bubble_messages: 1,
        voice_ok: 1,
        emoji_ok: 1,
      },
    },
    exported_at: '2026-10-27T12:00:00+08:00',
  });
  writeFile(dir, 'reader.css', Buffer.from('.bubble{border-radius:8px}\n', 'utf8'));
  writeFile(dir, 'index.html', Buffer.from('<!doctype html><html lang="zh-CN"><body>导出</body></html>', 'utf8'));

  return {
    dir,
    accounts: [ACCOUNT_A, ACCOUNT_B],
    accountNames: { [ACCOUNT_A]: 'Synthetic Account A', [ACCOUNT_B]: 'Synthetic Account B' },
    conversationA: CONVERSATION_A,
    conversationB: CONVERSATION_B,
    uuids: { ...UUID },
    media: { ...MEDIA },
    mediaHashes: { ...hashes },
    bigServerId: BIG_SERVER_ID,
    bigIndex: BIG_INDEX,
    bigFileBytes: BIG_FILE_BYTES,
    textFile: TEXT_FILE,
    cleanup() {
      // Windows briefly keeps SQLite handles open after close(); retry instead of
      // failing a passing test during teardown.
      for (let attempt = 0; attempt < 8; attempt += 1) {
        try {
          fs.rmSync(dir, { recursive: true, force: true });
          return;
        } catch (error) {
          if (attempt === 7) throw error;
          Atomics.wait(new Int32Array(new SharedArrayBuffer(4)), 0, 0, 50);
        }
      }
    },
  };
}

const IGNORED = /(^|[/\\])(reader\.sqlite|reader\.sqlite-wal|reader\.sqlite-shm|reader\.sqlite-journal)$/;

/** Recursively list files (relative, sorted), excluding reader.sqlite artifacts. */
export function listExportFiles(dir) {
  const found = [];
  const walk = (current) => {
    for (const entry of fs.readdirSync(current, { withFileTypes: true }).sort((a, b) => a.name.localeCompare(b.name))) {
      const absolute = path.join(current, entry.name);
      if (entry.isDirectory()) walk(absolute);
      else {
        const rel = path.relative(dir, absolute).split(path.sep).join('/');
        if (!IGNORED.test(rel)) found.push(rel);
      }
    }
  };
  walk(dir);
  return found.sort();
}

/** A stable digest of every original export file, so tests can prove no writes. */
export function hashExport(dir) {
  const digest = createHash('sha256');
  for (const rel of listExportFiles(dir)) {
    digest.update(rel);
    digest.update('\0');
    digest.update(createHash('sha256').update(fs.readFileSync(path.join(dir, rel))).digest('hex'));
    digest.update('\n');
  }
  return digest.digest('hex');
}

/** Copy an export to a new directory (simulates uploading/moving the export). */
export function copyExport(source, destination) {
  fs.cpSync(source, destination, { recursive: true });
  return destination;
}

export function readJson(dir, relative) {
  return JSON.parse(fs.readFileSync(path.join(dir, relative), 'utf8'));
}

/** True when this environment can create symlinks (used for traversal tests). */
export function canSymlink(testDir) {
  const target = path.join(testDir, 'symlink-target');
  const link = path.join(testDir, 'symlink-link');
  try {
    fs.writeFileSync(target, 'x');
    fs.symlinkSync(target, link, 'file');
    fs.rmSync(link, { force: true });
    fs.rmSync(target, { force: true });
    return true;
  } catch {
    return false;
  }
}